// Original, indexed low-poly furniture assets in normalized local coordinates.
function furnitureMesh(type){
 const vertices=[],faces=[],colours=[];
 function face(a,b,c,col){faces.push([a,b,c]);colours.push(col)}
 function rings(cx,cy,cz,rx,rz,levels,n,col,phase=0){
   const base=vertices.length;
   for(const [y,k] of levels)for(let i=0;i<n;i++){const a=phase+i*2*Math.PI/n;vertices.push([cx+rx*k*Math.cos(a),cy+y,cz+rz*k*Math.sin(a)])}
   for(let j=0;j<levels.length-1;j++)for(let i=0;i<n;i++){const a=base+j*n+i,b=base+j*n+(i+1)%n;face(a,b,b+n,col);face(a,b+n,a+n,col)}
   const end=base+(levels.length-1)*n;for(let i=1;i<n-1;i++){face(base,base+i+1,base+i,col);face(end,end+i,end+i+1,col)}
 }
 function box(x,y,z,w,h,d,b=.025,col=null){
   const v=vertices.length,bevel=Math.min(b,w/4,h/4,d/4),outline=(W,D)=>[[-W/2+bevel,-D/2],[W/2-bevel,-D/2],[W/2,-D/2+bevel],[W/2,D/2-bevel],[W/2-bevel,D/2],[-W/2+bevel,D/2],[-W/2,D/2-bevel],[-W/2,-D/2+bevel]];
   for(const [Y,W,D] of [[y,w-bevel,d-bevel],[y+bevel,w,d],[y+h-bevel,w,d],[y+h,w-bevel,d-bevel]])for(const [X,Z] of outline(W,D))vertices.push([x+X,Y,z+Z]);
   for(let j=0;j<3;j++)for(let i=0;i<8;i++){const a=v+j*8+i,b=v+j*8+(i+1)%8;face(a,b,b+8,col);face(a,b+8,a+8,col)}
   for(let i=1;i<7;i++){face(v,v+i+1,v+i,col);face(v+24,v+24+i,v+25+i,col)}
 }
 const frame='#53656a',fabric='#82999b',pale='#d5d9d0',wood='#9d8063';
 switch(type){
 case 'office_desk':box(0,.89,0,.98,.10,.98,.025);for(const x of [-.42,.42])for(const z of [-.38,.38])box(x,0,z,.055,.90,.09,.009,frame);box(.29,.30,0,.26,.55,.78,.018,wood);for(let j=0;j<3;j++)box(.29,.33+j*.16,.40,.22,.13,.025,.009);break;
 case 'office_chair':rings(0,0,0,.45,.45,[[.015,.9],[.065,1],[.095,.85]],5,frame);rings(0,.08,0,.08,.08,[[0,1],[.34,1]],12,frame);box(0,.42,0,.76,.13,.80,.045);box(0,.55,-.34,.77,.43,.17,.045);for(const x of [-.42,.42]){box(x,.48,0,.08,.22,.07,.01,frame);box(x,.69,0,.14,.07,.55,.02,frame)}break;
 case 'sofa':box(0,.05,0,.99,.28,.94,.045);box(0,.28,-.38,.97,.69,.22,.055);for(const x of [-.41,.41])box(x,.29,0,.17,.43,.91,.045);for(const x of [-.26,0,.26]){box(x,.34,.09,.25,.16,.67,.04,fabric);box(x,.49,-.24,.25,.40,.22,.035,fabric)}break;
 case 'round_table':rings(0,.90,0,.49,.49,[[0,.96],[.025,1],[.075,1],[.10,.96]],32,null);rings(0,.07,0,.11,.11,[[0,1],[.83,.85]],16,frame);rings(0,0,0,.31,.31,[[0,.9],[.05,1],[.09,.87]],24,frame);break;
 case 'bookshelf':for(const x of [-.46,.46])box(x,0,0,.08,1,.98,.012);box(0,0,-.47,.86,.99,.045,.008,wood);for(const y of [.02,.25,.49,.73,.96])box(0,y,0,.86,.04,.96,.01);for(const y of [.06,.30,.54])for(let i=0;i<6;i++)box(-.33+i*.12,y,-.1,.088,.16+(i%3)*.015,.60,.006,['#637b84','#c2a481','#84988c'][i%3]);break;
 case 'filing_cabinet':box(0,0,0,.99,1,.98,.035);for(let i=0;i<4;i++){const y=.03+i*.238;box(0,y,.465,.91,.22,.065,.016);box(0,y+.08,.505,.29,.033,.045,.009,frame);box(0,y+.15,.505,.20,.037,.015,.005,pale)}break;
 case 'single_bed':box(0,.02,0,.98,.19,.98,.025,wood);box(0,.21,.02,.91,.23,.91,.04,pale);box(0,.43,.29,.73,.12,.28,.035,'#e0e2d9');box(0,.44,-.12,.92,.09,.56,.025);box(0,0,.46,.98,.99,.075,.02,wood);break;
 case 'planter':rings(0,0,0,.36,.36,[[0,.66],[.30,.91],[.35,1]],18,'#ad8f72');rings(0,.34,0,.33,.33,[[0,1],[.025,1]],18,'#55483b');rings(0,.35,0,.035,.035,[[0,1],[.50,1]],10,'#677754');for(let i=0;i<7;i++){const a=i*2.4;const x=Math.cos(a)*.19,z=Math.sin(a)*.19;rings(x,.55+(i%3)*.10,z,.23,.20,[[0,.3],[.13,1],[.27,.12]],10,i%2?'#718c63':'#8fa87a')}break;
 }
 return{vertices,faces,colours};
}
